    expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B"})).toBeNull();
    expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "A"})).toBeNull();
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    await ui.setToday(pg_wes, "2026-04-22");
    await ui.showRetired(pg_wes, true);
    expect(await ui.dups(pg_wes)).toEqual([]);
    const c_dot_0 = ui.must(await ui.quickAdd(pg_wes, {"name": "Dot", "amount": "99.95"}));
